"""Seal all owned evidence and measured counts, with prior-file preservation."""
import importlib.util,json,subprocess,yaml
from pathlib import Path
B=Path(__file__).resolve().parents[1];sp=importlib.util.spec_from_file_location('stages',B/'target_stages.py');s=importlib.util.module_from_spec(sp);sp.loader.exec_module(s)
selection=json.loads((B/'selection.json').read_bytes());integration=json.loads((B/'review/final_integration/result.json').read_bytes());paths=set();table=[]
counts={'runs':0,'exact_records':0,'rejected_P4_mutations':0,'reviewed_generators':0,'reviewed_relations':0,'reviewed_compositions':0,'retained_failed_checkpoints':0,'retained_incomplete_native_checkpoints':0,'preparation_failures_retained':3,'review_write_failures_retained':1,'external_provider_calls':0,'chat_cost':'unmeasured'}
for row in selection['nodes']:
    run=s.ROOT/row['run'];review=run.parent.parent/'reviews/20261019_boundaries_audit';acc=json.loads((run/'accepted.json').read_bytes());prof=json.loads((run/'p0/profile.json').read_bytes());candidate=json.loads((run/acc['attempt']/'candidate.json').read_bytes());delta=yaml.safe_load((review/'operad_delta.yaml').read_bytes());mutants=json.loads((run/'p4/host_check.json').read_bytes())['predicate_results']['mutants']
    counts['runs']+=1;counts['exact_records']+=len(candidate['data']['records']);counts['rejected_P4_mutations']+=len(mutants);counts['retained_failed_checkpoints']+=len(acc['failed_checkpoints'])
    counts['retained_incomplete_native_checkpoints']+=len(acc.get('infrastructure_checkpoints',[]))
    for key,field in [('reviewed_generators','add_or_refine_generators'),('reviewed_relations','add_or_refine_relations'),('reviewed_compositions','checked_compositions')]:counts[key]+=len(delta[field])
    s.save(review/'review_result.json',{'task_id':row['node_id'],'status':'scoped_result_or_obstruction_reviewed','accepted':acc,'integration':integration,'claim_boundary':prof['claim_boundary'],'rejected_P4_mutations':len(mutants),'authority_effect':'None'})
    path=s.ROOT/row['operad_collection'];collection=yaml.safe_load(path.read_bytes());collection['latest_review']['status']='reviewed_with_targeted_native_integration';collection['latest_review']['final_integration']=(B/'review/final_integration/result.json').relative_to(s.ROOT).as_posix();path.write_bytes(yaml.safe_dump(collection,sort_keys=False,allow_unicode=True,width=100).encode());paths.add(path)
    for folder in (run,review):paths.update(p for p in folder.rglob('*') if p.is_file() and '__pycache__' not in p.parts)
    paths.add(run.parent.parent/'.gitattributes')
    for pin in candidate['source_pins']:paths.add(s.ROOT/pin['path'].split('/'+acc['attempt']+'/construction/',1)[1])
    table.append('| '+row['node_id']+' | '+prof['claim_boundary']['supports'].replace('|','/')+' | '+prof['claim_boundary']['does_not_support'].replace('|','/')+' |')
# Verify all pre-existing results, prompts and unrelated operad collections against Git blobs.
base=selection['base_commit'];selected={r['operad_collection'] for r in selection['nodes']};tracked=subprocess.check_output(['git','ls-tree','-rz',base,'--','dag/results','dag/prompts','dag/pfp/prompt_audit.json','dag/pfp/filename_custody.json','dag/operads'],cwd=s.ROOT).split(b'\0');preserved=[];old_files=[]
for line in tracked:
    if not line:continue
    meta,raw=line.split(b'\t',1);name=raw.decode();oid=meta.split()[-1].decode()
    if name=='dag/operads/index.json' or name in selected:continue
    old_files.append((name,oid))
actuals=subprocess.check_output(['git','hash-object','--no-filters','--stdin-paths'],input='\n'.join(n for n,_ in old_files)+'\n',cwd=s.ROOT,text=True).splitlines()
if len(actuals)!=len(old_files):raise ValueError('Preservation file coverage')
for (name,oid),actual in zip(old_files,actuals):
    p=s.ROOT/name
